diff --git a/index.js b/index.js
index 5ecd392..09032ea 100644
--- a/index.js
+++ b/index.js
@@ -81,7 +81,7 @@ export default function pLimit(concurrency) {
 					return;
 				}

-				const abortError = AbortSignal.abort().reason;
+				const abortError = createAbortError();

 				while (queue.size > 0) {
 					queue.dequeue().reject(abortError);
@@ -120,6 +120,15 @@ export function limitFunction(function_, options) {
 	return (...arguments_) => limit(() => function_(...arguments_));
 }

+function createAbortError() {
+	// A native `Error` rather than the `DOMException` from `AbortSignal.abort()`,
+	// so the rejection reason passes `util.types.isNativeError()` and the usual
+	// error-handling checks consumers apply.
+	const error = new Error('The queue was cleared');
+	error.name = 'AbortError';
+	return error;
+}
+
 function validateConcurrency(concurrency) {
 	if (!((Number.isInteger(concurrency) || concurrency === Number.POSITIVE_INFINITY) && concurrency > 0)) {
 		throw new TypeError('Expected `concurrency` to be a number from 1 and up');
